/**
 * Bay Area Life 2.0 — Stage 1 slice city data (Shenzhen vertical slice).
 *
 * Pure data module: NO three.js, NO DOM. The snapshot is
 * `./data/slice-city.json`, generated by `tools/fetch_slice.py` from
 * OpenStreetMap via Overpass (bbox B: 22.5465–22.5510 N, 113.9490–113.9540 E,
 * Nanshan Science Park core) and versioned with its OSM base timestamp.
 * Runtime code never talks to Overpass; it only reads this snapshot.
 *
 * Coordinates are ENU metres from the bbox centre
 * (origin lat 22.54875, lon 113.9515): +x east, +z south — the same
 * convention as the 1.0 map (x east / z south).
 *
 * Data (c) OpenStreetMap contributors, ODbL.
 */

import sliceCityJson from "./data/slice-city.json";

export interface SliceBuilding {
  id: string;
  osmId: number;
  name: string | null;
  kind: "office" | "commercial" | "residential" | "public" | "other";
  /** Closed [x, z] polygon in ENU metres (first point == last point). */
  footprint: [number, number][];
  /** Height in metres. */
  height: number;
  levels: number;
  enterable: null | { role: "office" | "shop" | "lobby"; note: string };
}

export interface SliceRoad {
  id: string;
  osmId: number;
  name: string | null;
  /** OSM highway value: primary/secondary/tertiary/residential/service/
   *  footway/unclassified/secondary_link/... */
  kind: string;
  /** Centreline in ENU metres. */
  points: [number, number][];
}

export interface SliceCity {
  version: string;
  /** OSM database timestamp the snapshot was built from (osm3s). */
  timestamp_osm_base: string;
  bbox: { minLat: number; maxLat: number; minLon: number; maxLon: number };
  origin: { lat: number; lon: number };
  source: string;
  buildings: SliceBuilding[];
  roads: SliceRoad[];
  /**
   * Walkable ground polygons in ENU metres (each closed).
   *
   * Derivation rule (see tools/fetch_slice.py), v1.1:
   *  - footway/path/pedestrian/steps/cycleway centrelines buffered to a
   *    2 m half-width corridor (4 m wide strip), one rectangle per segment;
   *  - residential/service/unclassified/living_street/tertiary roads get a
   *    3 m sidewalk strip along BOTH sides (band 3–6 m from the centreline);
   *  - the carriageway surface of EVERY road is walkable too (centred
   *    strip, half-width by kind). v1.0 had sidewalks only and produced
   *    156 disconnected fragments with no cross-block route, so the
   *    delivery task and NPC commuting were unroutable; Stage 1 has no
   *    vehicle-traffic AI, so pedestrians on the carriageway is the
   *    working rule until Stage 2 re-splits it with crosswalks + traffic;
   *  - v1.2: sidewalk bands 2–5.5 m from the centreline (overlap the
   *    carriageway, no stranded fragments), and each enterable building
   *    gets a 3 m wide entrance apron from its door to the nearest road;
   *  - plaza/park/garden area ways contribute their whole polygon.
   */
  walkable: [number, number][][];
}

/** Metres per degree of latitude (1 deg lat ~= 111320 m). */
export const M_PER_DEG = 111320;

/**
 * The versioned slice snapshot. Imported statically (bundled); the JSON is
 * the single source of truth — do not mutate the returned object.
 */
export function loadSliceCity(): SliceCity {
  return sliceCityJson as SliceCity;
}

/** Convert WGS84 lat/lon to ENU metres relative to a given origin. */
export function latLonToEnu(
  lat: number,
  lon: number,
  origin: { lat: number; lon: number },
): [number, number] {
  const x = (lon - origin.lon) * M_PER_DEG * Math.cos((origin.lat * Math.PI) / 180);
  const z = (origin.lat - lat) * M_PER_DEG;
  return [x, z];
}

/** Convert ENU metres back to WGS84 lat/lon relative to a given origin. */
export function enuToLatLon(
  x: number,
  z: number,
  origin: { lat: number; lon: number },
): [number, number] {
  const lat = origin.lat - z / M_PER_DEG;
  const lon = origin.lon + x / (M_PER_DEG * Math.cos((origin.lat * Math.PI) / 180));
  return [lat, lon];
}

/** Footprint area in m^2 (shoelace formula; polygon need not be closed). */
export function buildingAreaM2(building: SliceBuilding): number {
  const fp = building.footprint;
  let a = 0;
  for (let i = 0; i < fp.length; i++) {
    const p = fp[i] as [number, number];
    const q = fp[(i + 1) % fp.length] as [number, number];
    a += p[0] * q[1] - q[0] * p[1];
  }
  return Math.abs(a) / 2;
}
